<?php require_once __DIR__.'/../includes/bootstrap.php'; if(!empty($_SESSION['user'])){header('Location: ../student/dashboard.php');exit;} $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$password=$_POST['password']??'';$department=trim($_POST['department']??'');$year=trim($_POST['year']??''); if(mb_strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8||$department===''||$year==='')$error='Enter valid details. Password must be at least 8 characters.';else{try{$pdo->beginTransaction();$q=$pdo->prepare('INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,'student')');$q->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT)]);$id=(int)$pdo->lastInsertId();$q=$pdo->prepare('INSERT INTO student_profiles(user_id,department,year_of_study) VALUES(?,?,?)');$q->execute([$id,$department,$year]);$pdo->commit();session_regenerate_id(true);$_SESSION['user']=['id'=>$id,'name'=>$name,'email'=>$email,'role'=>'student'];flash('Your student account was created.');header('Location: ../student/dashboard.php');exit;}catch(PDOException $ex){if($pdo->inTransaction())$pdo->rollBack();$error=$ex->getCode()==='23000'?'An account with this email already exists.':'Unable to create account. Check the database setup.';}}} header_html('Student Registration'); ?>
<div class="form-card"><h1>Create student account</h1><p class="muted">Register to apply for internships and placements.</p><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="field"><label>Full name</label><input name="name" required minlength="2" maxlength="100" value="<?=e($_POST['name']??'')?>"></div><div class="field"><label>Email</label><input type="email" name="email" required maxlength="190" value="<?=e($_POST['email']??'')?>"></div><div class="field"><label>Password (minimum 8 characters)</label><input type="password" name="password" required minlength="8" autocomplete="new-password"></div><div class="field"><label>Department</label><select name="department" required><option value="">Choose department</option><option>Computer Science & Engineering</option><option>Information Technology</option><option>Electronics & Communication</option><option>Mechanical Engineering</option><option>Other</option></select></div><div class="field"><label>Year of study</label><select name="year" required><option value="">Choose year</option><option>1st Year</option><option>2nd Year</option><option>3rd Year</option><option>4th Year</option></select></div><button type="submit">Register</button></form><p class="small">Already registered? <a href="login.php">Sign in</a></p></div><?php footer_html(); ?>
